import bisect

# Load symbols
syms = []
with open('/tmp/funcs.txt') as f:
    for line in f:
        parts = line.strip().split(None, 1)
        if len(parts) == 2:
            syms.append((int(parts[0], 16), parts[1]))
syms.sort()
keys = [s[0] for s in syms]

addrs = [0x222098, 0x2241ac, 0x1abc80, 0x1abd14, 0x16dfa4, 0x16db6c, 0x16de04]

for addr in addrs:
    idx = bisect.bisect_right(keys, addr) - 1
    if idx >= 0:
        base, name = syms[idx]
        # Also show next symbol for context
        if idx + 1 < len(syms):
            next_base, next_name = syms[idx+1]
            print(f'0x{addr:06x}  {name}+0x{addr-base:x}  (next: {next_name} @ 0x{next_base:x}, gap={next_base-addr})')
        else:
            print(f'0x{addr:06x}  {name}+0x{addr-base:x}')
